SELECT CASE WHEN s.sqft >= 12694 THEN 'high' WHEN s.sqft >= 4378 THEN 'mid' ELSE 'low' END AS sqft_bucket, CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, SUM(o.discount) AS total_discount FROM orders o INNER JOIN stores s ON o.store_id = s.id INNER JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN s.sqft >= 12694 THEN 'high' WHEN s.sqft >= 4378 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END;
